-- GJ01 + GJ27 + GJ38 at year grain, for the Details card.
-- Summed per maker: the three RTOs share most of their makers,
-- so a plain UNION would list the same maker three times at a
-- third of its volume each.
CREATE VIEW "Ahmedabad_Class_Wise" WITH (security_invoker = on) AS
SELECT
    "year",
    "Maker",
    sum("Three Wheeler (Goods)")::integer AS "Three Wheeler (Goods)",
    sum("M-Cycle/Scooter")::integer AS "M-Cycle/Scooter",
    sum("Construction Equipment Vehicle")::integer AS "Construction Equipment Vehicle",
    sum("Crane Mounted Vehicle")::integer AS "Crane Mounted Vehicle",
    sum("Earth Moving Equipment")::integer AS "Earth Moving Equipment",
    sum("Bus")::integer AS "Bus",
    sum("Goods Carrier")::integer AS "Goods Carrier",
    sum("Mobile Clinic")::integer AS "Mobile Clinic",
    sum("Moped")::integer AS "Moped",
    sum("Three Wheeler (Passenger)")::integer AS "Three Wheeler (Passenger)",
    sum("e-Rickshaw with Cart (G)")::integer AS "e-Rickshaw with Cart (G)",
    sum("Motor Car")::integer AS "Motor Car",
    sum("Trailer (Agricultural)")::integer AS "Trailer (Agricultural)",
    sum("Motor Cab")::integer AS "Motor Cab",
    sum("Agricultural Tractor")::integer AS "Agricultural Tractor",
    sum("Tractor (Commercial)")::integer AS "Tractor (Commercial)",
    sum("e-Rickshaw(P)")::integer AS "e-Rickshaw(P)",
    sum("Ambulance")::integer AS "Ambulance",
    sum("Camper Van / Trailer")::integer AS "Camper Van / Trailer",
    sum("Camper Van / Trailer (Private Use)")::integer AS "Camper Van / Trailer (Private Use)",
    sum("Maxi Cab")::integer AS "Maxi Cab",
    sum("Adapted Vehicle")::integer AS "Adapted Vehicle",
    sum("M-Cycle/Scooter-With Side Car")::integer AS "M-Cycle/Scooter-With Side Car",
    sum("Motor Cycle/Scooter-Used For Hire")::integer AS "Motor Cycle/Scooter-Used For Hire",
    sum("Excavator (NT)")::integer AS "Excavator (NT)",
    sum("Fork Lift")::integer AS "Fork Lift",
    sum("Cash Van")::integer AS "Cash Van",
    sum("Fire Fighting Vehicle")::integer AS "Fire Fighting Vehicle",
    sum("Motorised Cycle (CC  25cc)")::integer AS "Motorised Cycle (CC  25cc)",
    sum("Trailer (Commercial)")::integer AS "Trailer (Commercial)",
    sum("Articulated Vehicle")::integer AS "Articulated Vehicle",
    sum("Recovery Vehicle")::integer AS "Recovery Vehicle",
    sum("Omni Bus (Private Use)")::integer AS "Omni Bus (Private Use)",
    sum("Fire Tenders")::integer AS "Fire Tenders",
    sum("Tower Wagon")::integer AS "Tower Wagon",
    sum("Vehicle Fitted With Generator")::integer AS "Vehicle Fitted With Generator",
    sum("Three Wheeler (Personal)")::integer AS "Three Wheeler (Personal)",
    sum("Private Service Vehicle (Individual Use)")::integer AS "Private Service Vehicle (Individual Use)",
    sum("Quadricycle (Private)")::integer AS "Quadricycle (Private)",
    sum("Dumper")::integer AS "Dumper",
    sum("Armoured/Specialised Vehicle")::integer AS "Armoured/Specialised Vehicle",
    sum("Mobile Workshop")::integer AS "Mobile Workshop",
    sum("Omni Bus")::integer AS "Omni Bus",
    sum("Vehicle Fitted With Rig")::integer AS "Vehicle Fitted With Rig",
    sum("Harvester")::integer AS "Harvester",
    sum("Animal Ambulance")::integer AS "Animal Ambulance",
    sum("Semi-Trailer (Commercial)")::integer AS "Semi-Trailer (Commercial)",
    sum("Educational Institution Bus")::integer AS "Educational Institution Bus",
    sum("Road Roller")::integer AS "Road Roller",
    sum("Total")::integer AS "Total"
FROM (
    SELECT "year", "Maker", "Three Wheeler (Goods)", "M-Cycle/Scooter", "Construction Equipment Vehicle", "Crane Mounted Vehicle", "Earth Moving Equipment", "Bus", "Goods Carrier", "Mobile Clinic", "Moped", "Three Wheeler (Passenger)", "e-Rickshaw with Cart (G)", "Motor Car", "Trailer (Agricultural)", "Motor Cab", "Agricultural Tractor", "Tractor (Commercial)", "e-Rickshaw(P)", "Ambulance", "Camper Van / Trailer", "Camper Van / Trailer (Private Use)", "Maxi Cab", "Adapted Vehicle", "M-Cycle/Scooter-With Side Car", "Motor Cycle/Scooter-Used For Hire", "Excavator (NT)", "Fork Lift", "Cash Van", "Fire Fighting Vehicle", "Motorised Cycle (CC  25cc)", "Trailer (Commercial)", "Articulated Vehicle", "Recovery Vehicle", "Omni Bus (Private Use)", "Fire Tenders", "Tower Wagon", "Vehicle Fitted With Generator", "Three Wheeler (Personal)", "Private Service Vehicle (Individual Use)", "Quadricycle (Private)", "Dumper", "Armoured/Specialised Vehicle", "Mobile Workshop", "Omni Bus", NULL::integer AS "Vehicle Fitted With Rig", NULL::integer AS "Harvester", NULL::integer AS "Animal Ambulance", NULL::integer AS "Semi-Trailer (Commercial)", NULL::integer AS "Educational Institution Bus", NULL::integer AS "Road Roller", "Total"
    FROM "Maker_Class_Wise_GJ01"
    UNION ALL
    SELECT "year", "Maker", "Three Wheeler (Goods)", "M-Cycle/Scooter", "Construction Equipment Vehicle", "Crane Mounted Vehicle", "Earth Moving Equipment", "Bus", "Goods Carrier", NULL::integer AS "Mobile Clinic", "Moped", "Three Wheeler (Passenger)", "e-Rickshaw with Cart (G)", "Motor Car", "Trailer (Agricultural)", "Motor Cab", "Agricultural Tractor", "Tractor (Commercial)", "e-Rickshaw(P)", "Ambulance", "Camper Van / Trailer", "Camper Van / Trailer (Private Use)", "Maxi Cab", "Adapted Vehicle", "M-Cycle/Scooter-With Side Car", "Motor Cycle/Scooter-Used For Hire", "Excavator (NT)", "Fork Lift", NULL::integer AS "Cash Van", "Fire Fighting Vehicle", "Motorised Cycle (CC  25cc)", "Trailer (Commercial)", "Articulated Vehicle", "Recovery Vehicle", NULL::integer AS "Omni Bus (Private Use)", NULL::integer AS "Fire Tenders", "Tower Wagon", "Vehicle Fitted With Generator", NULL::integer AS "Three Wheeler (Personal)", "Private Service Vehicle (Individual Use)", NULL::integer AS "Quadricycle (Private)", "Dumper", NULL::integer AS "Armoured/Specialised Vehicle", NULL::integer AS "Mobile Workshop", NULL::integer AS "Omni Bus", "Vehicle Fitted With Rig", "Harvester", "Animal Ambulance", "Semi-Trailer (Commercial)", NULL::integer AS "Educational Institution Bus", NULL::integer AS "Road Roller", "Total"
    FROM "Maker_Class_Wise_GJ27"
    UNION ALL
    SELECT "year", "Maker", "Three Wheeler (Goods)", "M-Cycle/Scooter", "Construction Equipment Vehicle", "Crane Mounted Vehicle", "Earth Moving Equipment", "Bus", "Goods Carrier", NULL::integer AS "Mobile Clinic", "Moped", "Three Wheeler (Passenger)", "e-Rickshaw with Cart (G)", "Motor Car", "Trailer (Agricultural)", "Motor Cab", "Agricultural Tractor", "Tractor (Commercial)", "e-Rickshaw(P)", "Ambulance", NULL::integer AS "Camper Van / Trailer", NULL::integer AS "Camper Van / Trailer (Private Use)", "Maxi Cab", "Adapted Vehicle", "M-Cycle/Scooter-With Side Car", NULL::integer AS "Motor Cycle/Scooter-Used For Hire", NULL::integer AS "Excavator (NT)", "Fork Lift", NULL::integer AS "Cash Van", "Fire Fighting Vehicle", "Motorised Cycle (CC  25cc)", NULL::integer AS "Trailer (Commercial)", NULL::integer AS "Articulated Vehicle", "Recovery Vehicle", NULL::integer AS "Omni Bus (Private Use)", "Fire Tenders", NULL::integer AS "Tower Wagon", NULL::integer AS "Vehicle Fitted With Generator", NULL::integer AS "Three Wheeler (Personal)", "Private Service Vehicle (Individual Use)", NULL::integer AS "Quadricycle (Private)", "Dumper", NULL::integer AS "Armoured/Specialised Vehicle", NULL::integer AS "Mobile Workshop", "Omni Bus", NULL::integer AS "Vehicle Fitted With Rig", "Harvester", NULL::integer AS "Animal Ambulance", NULL::integer AS "Semi-Trailer (Commercial)", "Educational Institution Bus", "Road Roller", "Total"
    FROM "Maker_Class_Wise_GJ38"
) AS "parts"
GROUP BY "year", "Maker";

GRANT SELECT ON "Ahmedabad_Class_Wise" TO anon, authenticated;

